/* Interface responsiva. Sem dependências externas e sem envio de dados pessoais. */
(function(){'use strict';
const J=window.Jarvis,C=J.C;let storage;try{storage=window.localStorage;}catch{}const store=new J.Store(storage);
const S={drawer:false,tab:'theory',filter:'all',discipline:'all',search:'',errorFilter:'pending',busy:false,session:null,quiz:null,reviewTab:'pending',simScope:'studied'};
let pendingImport=null,lastFocus=null,timer=null;const app=document.getElementById('app');
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',book:'M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1m0-15c3-2 6-2 10-1v15c-4-1-7-1-10 1V5',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6Zm-4 10 3 3 5-6',scale:'M12 3v18m-6 0h12M4 7h16M5 7l-4 8h8Zm14 0-4 8h8Z',building:'m2 8 10-6 10 6ZM4 10v9m5-9v9m6-9v9m5-9v9M2 22h20',network:'M9 3h6v6H9ZM1 16h6v6H1Zm16 0h6v6h-6ZM12 9v4M4 16v-3h16v3',monitor:'M2 3h20v14H2Zm10 14v5m-5 0h10',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-4M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8m9 0a4 4 0 0 1 0 8',clock:'M12 8v5l3 2M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20',chart:'M4 20V10m8 10V3m8 17v-7',more:'M5 12h.01M12 12h.01M19 12h.01',arrow:'M5 12h14m-6-6 6 6-6 6',back:'M19 12H5m6-6-6 6 6 6',chevron:'m9 5 7 7-7 7',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',menu:'M3 5h18M3 12h18M3 19h18',search:'M21 21l-5-5M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14',refresh:'M3 11a9 9 0 1 1 2 7M3 3v8h8',error:'M12 8v5m0 4h.01M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20',file:'M14 2H4v20h16V8Zm0 0v6h6M8 12h8m-8 4h8',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M10 2h4l1 3 3 1 3-1 2 4-2 2v3l2 2-2 4-3-1-3 1-1 3h-4l-1-3-3-1-3 1-2-4 2-2v-3L1 9l2-4 3 1 3-1Z',download:'M12 3v12m-5-5 5 5 5-5M3 16v5h18v-5',upload:'M12 15V3m-5 5 5-5 5 5M3 16v5h18v-5',save:'M4 3h14l3 3v15H3V3Zm3 0v6h10V3M7 21v-7h10v7',external:'M14 3h7v7m0-7L10 14m0-11H3v18h18v-7',list:'M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01',flag:'M4 22V3c5-4 10 4 16 0v11c-6 4-11-4-16 0',play:'m8 4 13 8-13 8Z',moon:'M20 14a9 9 0 1 1-10-12 7 7 0 0 0 10 12',sun:'M12 1v2m0 18v2M1 12h2m18 0h2M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10',volume:'M11 4 5 9H2v6h3l6 5Zm4 4a5 5 0 0 1 0 8m3-11a9 9 0 0 1 0 14',database:'M3 6c0-5 18-5 18 0S3 11 3 6Zm0 0v12c0 5 18 5 18 0V6M3 12c0 5 18 5 18 0'};
const ic=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.file}"/></svg>`;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const db=()=>store.db,ae=()=>J.active(db()),st=id=>J.topicState(db(),id),disc=id=>C.disciplines.find(d=>d.id===id),lesson=id=>C.lessons.find(l=>l.id===id);
const date=x=>new Date(x).toLocaleDateString('pt-BR',{day:'2-digit',month:'short',year:'numeric'});
const statuses={novo:'Não iniciado',visto:'Visto',consolidacao:'Em consolidação',dominado:'Dominado'};
const colorStatus=s=>s==='dominado'?'green':s==='consolidacao'?'amber':s==='visto'?'cyan':'';
const badge=(text,cls='')=>`<span class="pill ${cls}">${esc(text)}</span>`;
const btn=(text,action,cls='',attrs='')=>`<button class="btn ${cls}" data-act="${action}" ${attrs}>${text}</button>`;
const link=(text,href,cls='')=>`<a class="btn ${cls}" href="${href}">${text}</a>`;
const header=(title,sub='',action='')=>`<div class="page-header"><div><div class="eyebrow">JARVIS ESTUDANTE / INSS</div><h1>${title}</h1>${sub?`<p class="muted">${sub}</p>`:''}</div>${action}</div>`;
const notice=(text,warning=false)=>`<div class="notice ${warning?'warning':''}">${ic(warning?'error':'shield')}<span>${text}</span></div>`;
const empty=(title,text,action='',icon='book')=>`<div class="panel empty">${ic(icon)}<h2>${title}</h2><p>${text}</p>${action}</div>`;
const bar=(value,accent='')=>`<div class="progress" ${accent?`style="--accent:${accent}"`:''}><span style="width:${Math.max(0,Math.min(100,value))}%"></span></div>`;
const names={home:'Início',courses:'Trilha de conteúdos',lesson:'Área de estudo',questions:'Questões',errors:'Banco de erros',reviews:'Revisões',sim:'Simulados',result:'Resultado',map:'Mapa cumulativo',history:'Histórico de sessões',sources:'Fontes oficiais',settings:'Configurações e backup',more:'Seu espaço de estudos'};
const navs=[['home','home'],['courses','book'],['questions','file'],['errors','error'],['reviews','refresh'],['sim','flag'],['map','network'],['history','clock'],['sources','external'],['settings','settings']];
function route(){const [page='home',id='']=location.hash.slice(1).split('/');return{page:names[page]?page:'home',id};}
function source(l){const s=C.sources[l.source];return s[1]?`<a href="${s[1]}" target="_blank" rel="noopener noreferrer" class="row gap-sm">${ic('external')}<span>${esc(s[0])}</span></a>`:`<span class="muted">${esc(s[0])}</span>`;}
function notify(text,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=text;document.getElementById('toasts').append(el);setTimeout(()=>el.remove(),5500);}
function persistDraft(){try{storage?.setItem(J.DRAFT,JSON.stringify({session:S.session,quiz:S.quiz}));}catch{notify('Não foi possível salvar a sessão em andamento. Exporte seu backup.',true);}}
try{const raw=storage?.getItem(J.DRAFT);if(raw){const v=JSON.parse(raw);if(v.session?.cycle===J.cycle(db())&&lesson(v.session.topic)){S.session=v.session;if(v.quiz&&Array.isArray(v.quiz.ids)&&v.quiz.ids.length<=C.lessons.length*4&&v.quiz.ids.every(id=>J.question(id))&&v.quiz.answers&&typeof v.quiz.answers==='object')S.quiz=v.quiz;}}}catch{notify('A sessão em andamento não pôde ser recuperada. O histórico concluído está preservado.',true);}
async function save(events=[],prefs=null){try{await store.commit(events,prefs);return true;}catch(e){notify(e.message,true);return false;}}
function event(type,payload={}){return J.ev(type,payload,J.cycle(db()));}
function startSession(l,mode='learn'){if(!S.session){S.session={id:J.uid(),topic:l.id,cycle:J.cycle(db()),started:new Date().toISOString(),mode};persistDraft();}}
function go(hash){S.drawer=false;if(location.hash==='#'+hash)render();else location.hash=hash;}
function applyPrefs(){document.documentElement.dataset.theme=db().prefs.theme;document.documentElement.style.fontSize=db().prefs.font+'px';}
function shell(content){const r=route(),current=r.page==='lesson'?'courses':r.page==='result'?'sim':r.page;const mark=store.error?'Falha ao salvar':'Salvo neste dispositivo';return`<div class="drawer-overlay ${S.drawer?'open':''}" data-act="drawer-close"></div><aside class="sidebar ${S.drawer?'open':''}" aria-label="Navegação principal" ${!S.drawer&&matchMedia('(max-width:900px)').matches?'inert':''}><button class="icon-btn drawer-close" data-act="drawer-close" aria-label="Fechar menu">${ic('close')}</button><a class="brand" href="#home"><img src="assets/icon.svg" alt=""><span><strong>JARVIS</strong><small>ESTUDANTE</small></span></a><div class="caps muted" style="padding-left:15px">SEU ESPAÇO DE ESTUDOS</div><nav>${navs.map(([p,i])=>`<a class="navlink ${current===p?'active':''}" href="#${p}" ${current===p?'aria-current="page"':''}>${ic(i)}${names[p]}</a>`).join('')}</nav><div class="sidebar-foot"><div class="row gap-sm cyan">${ic('shield')}<strong style="font-size:.8rem">Um passo de cada vez.</strong></div><p class="muted" style="font-size:.75rem;margin-top:9px">Seu desempenho orienta o ritmo. Visto não é dominado.</p><div class="live-label top-gap"><span class="dot green"></span>Dados somente neste navegador</div></div></aside><div class="workspace"><header class="topbar"><div class="row"><button class="icon-btn mobile-menu" data-act="drawer" aria-label="Abrir menu">${ic('menu')}</button><div class="mobile-brand"><a class="brand" href="#home"><img src="assets/icon.svg" alt=""><span><strong>JARVIS</strong><small>ESTUDANTE</small></span></a></div><div class="breadcrumb"><span class="muted">Meu espaço</span><span class="muted"> / </span><strong style="font-size:.85rem">${names[r.page]}</strong></div></div><div class="row"><div class="live-label"><span class="dot ${store.error?'red':'green'}"></span><span>${mark}</span></div><button class="icon-btn" data-act="theme" aria-label="Alternar tema">${ic(db().prefs.theme==='dark'?'sun':'moon')}</button><div class="avatar" aria-hidden="true">${esc((db().prefs.name||'JE').slice(0,2).toUpperCase())}</div></div></header>${store.error?`<div class="storage-banner">${esc(store.error)} ${btn('Exportar agora','export','small')}</div>`:''}<main id="main" class="main" tabindex="-1">${content}<div class="footer-note">JARVIS Estudante • INSS / CEBRASPE · Conteúdo autoral introdutório, base histórica do edital 2022. Confira as fontes e o edital aplicável. Progresso local, sem sincronização na nuvem.</div></main></div><nav class="bottom-nav" aria-label="Atalhos">${[['home','home','Início'],['courses','book','Estudar'],['reviews','refresh','Revisar'],['map','chart','Progresso'],['more','more','Mais']].map(([p,i,t])=>`<a href="#${p}" class="${current===p||p==='map'&&current==='history'?'active':''}">${ic(i)}${t}</a>`).join('')}</nav>`;}
function courseCard(d){const ls=C.lessons.filter(l=>l.d===d.id),done=ls.filter(l=>st(l.id).mastered).length,seen=ls.filter(l=>st(l.id).seen).length;return`<a class="panel course" style="--accent:${d.color};color:var(--text);text-decoration:none" href="#courses/${d.id}"><div class="course-icon">${ic(d.icon)}</div><div class="grow"><div class="row between wrap"><h3>${esc(d.name)}</h3>${d.priority>=4?badge(d.tag,d.id==='prev'?'red':'cyan'):''}</div><small>${seen}/${ls.length} módulos vistos · ${done} dominados</small>${bar(done/ls.length*100,d.color)}</div>${ic('chevron')}</a>`;}
function home(){const rec=J.recommend(db()),l=rec.lesson,s=J.stats(db()),ses=ae().filter(e=>e.type==='session'),seen=C.lessons.filter(l=>st(l.id).seen).length,mastered=C.lessons.filter(l=>st(l.id).mastered).length,hour=Number(new Intl.DateTimeFormat('pt-BR',{hour:'numeric',hour12:false,timeZone:'America/Fortaleza'}).format(new Date())),greeting=hour<12?'Bom dia':hour<18?'Boa tarde':'Boa noite';const due=C.lessons.filter(l=>{const d=J.dueDate(db(),l.id);return d&&d<=new Date();});return header(`${greeting}${db().prefs.name?', '+esc(db().prefs.name):''}. Vamos evoluir?`,'Seu estudo organizado, do primeiro conceito à aplicação em prova.',badge('INSS • foco CEBRASPE','cyan'))+`<div class="home-grid"><div><section class="panel hero"><div class="hero-symbol">${ic('book')}</div>${badge(ses.length?'PRÓXIMO PASSO RECOMENDADO':'SEU PRIMEIRO PASSO')}<h2>${esc(l.title)}</h2><p>${esc(rec.reason)}</p><div class="row wrap">${link(ic('play')+(S.session?'Continuar estudo':`Começar Dia ${ses.length+1}`),S.quiz?'#questions':'#lesson/'+l.id,'primary')}${link('Ver minha trilha','#courses','ghost')}</div><small style="display:block;margin-top:18px;color:#bdd3e7">Teoria → exemplos → 2 questões → diagnóstico</small></section><div class="grid3 stats-grid top-gap"><div class="panel stat">${ic('clock')}<strong>${ses.length}</strong><small>Sessões concluídas</small></div><div class="panel stat">${ic('file')}<strong>${s.total}</strong><small>Questões respondidas</small></div><div class="panel stat">${ic('shield')}<strong>${mastered}</strong><small>Tópicos dominados</small></div></div><div class="section-title"><h2>Hoje no seu plano</h2><a href="#courses" style="font-size:.8rem">Ver disciplinas ${ic('chevron')}</a></div><div class="stack">${courseCard(C.disciplines[0])}${courseCard(C.disciplines[1])}</div></div><aside class="stack home-side"><section class="panel"><div class="row between bottom-gap"><h2>Seu ciclo</h2>${ic('network')}</div><div class="row between"><span class="metric-label">Módulos vistos</span><strong>${seen}/${C.lessons.length}</strong></div>${bar(seen/C.lessons.length*100)}<div class="row between top-gap"><span class="metric-label">Aproveitamento em itens</span><strong>${s.total?s.accuracy+'%':'—'}</strong></div>${bar(s.accuracy)}<p style="font-size:.8rem;margin:18px 0">O ritmo depende da compreensão. Um acerto isolado não prova domínio.</p>${link('Abrir mapa cumulativo','#map','full')}</section><section class="panel"><div class="row gap-sm bottom-gap cyan">${ic('refresh')}<h3>Revisão no momento certo</h3></div><p style="font-size:.88rem">${due.length?`${due.length} tópico(s) com revisão pendente.`:seen?'Nenhuma revisão vencida. Você pode praticar os conteúdos vistos.':'Suas revisões aparecem depois do primeiro estudo.'}</p><div class="top-gap">${link(due.length?'Revisar agora':'Ver revisões','#reviews','full outline')}</div></section><section class="notice">${ic('database')}<div><strong>Seu progresso fica aqui.</strong><br>Faça backups para guardar uma cópia fora do navegador. <a href="#settings">Exportar backup</a></div></section></aside></div>`;}
function filteredLessons(d){return C.lessons.filter(l=>(!d||l.d===d)&&(!S.search||(l.title+' '+l.core).toLocaleLowerCase('pt-BR').includes(S.search.toLocaleLowerCase('pt-BR')))&&(S.filter==='all'||st(l.id).status===S.filter));}
function topicRow(l,i){const state=st(l.id);return`<div class="panel topic-row"><span class="status-circle ${state.status}">${state.mastered?ic('check'):i+1}</span><div class="grow"><h3>${esc(l.title)}</h3><div class="row wrap gap-sm" style="margin-top:6px">${badge(statuses[state.status],colorStatus(state.status))}<small>${l.minutes} min · ${l.questions.length} itens</small></div></div>${link(ic('chevron'),'#lesson/'+l.id,'small ghost')}</div>`;}
function courses(id){const d=disc(id);return header(d?esc(d.name):'Trilha de conteúdos',d?'Construa a base, aplique e revise. Nenhum módulo é bloqueado.':'Sete disciplinas. Um método que acompanha sua compreensão.',d?link(ic('back')+'Disciplinas','#courses','small'):'' )+`<div class="search">${ic('search')}<input id="topic-search" placeholder="Buscar assunto" value="${esc(S.search)}" aria-label="Buscar assunto"></div><div class="filters">${[['all','Todos'],['novo','Não iniciados'],['visto','Vistos'],['consolidacao','Consolidação'],['dominado','Dominados']].map(([k,v])=>`<button class="chip ${S.filter===k?'active':''}" data-act="filter" data-value="${k}" aria-pressed="${S.filter===k}">${v}</button>`).join('')}</div>${d||S.search||S.filter!=='all'?`<div id="topic-results" class="lesson-list">${filteredLessons(d?.id).map(topicRow).join('')||empty('Nenhum tópico encontrado','Altere a busca ou os filtros.')}</div>`:`<div class="grid2">${C.disciplines.map(courseCard).join('')}</div>`}<div class="top-gap">${notice('Esta biblioteca contém módulos introdutórios. O mapa também mantém uma lista de aprofundamentos; a cobertura de um edital completo depende de estudo adicional e conferência das fontes.')}</div>`;}
const steps=['Núcleo da regra','Elementos e requisitos','Limites e exceções','Conceitos próximos','Caso concreto','Formulação de prova','Recuperação ativa','Transferência'];
function latestNote(id){return ae().filter(e=>e.type==='note'&&e.topic===id).at(-1)?.text||'';}
function study(id){const l=lesson(id)||J.recommend(db()).lesson,d=disc(l.d),state=st(l.id);const tab=S.tab;const body=tab==='theory'?`<article class="panel reading"><div class="row between wrap bottom-gap">${badge(d.short,'cyan')}${badge(statuses[state.status],colorStatus(state.status))}</div><h2>${esc(l.title)}</h2><div class="definition">${esc(l.core)}</div><h3>Entenda a regra</h3><p>${esc(l.rule)}</p><h3>Limites e condições</h3><p>${esc(l.limit)}</p><div class="rulebox">${source(l)}</div><div class="row wrap top-gap">${btn(ic('volume')+'Ouvir texto','speak','small',`data-topic="${l.id}"`)}${btn(ic('check')+'Li e compreendi a introdução','read','primary',`data-topic="${l.id}"`)}</div></article>`:tab==='examples'?`<article class="panel reading"><h2>Do conceito ao caso</h2><h3>Uma situação concreta</h3><p>${esc(l.example)}</p><h3>Compare antes de concluir</h3><p>${esc(l.contrast)}</p><h3>Agora, transfira</h3><p>Crie outro caso mudando um requisito ou uma condição. A conclusão continua válida? Explique a regra e o detalhe decisivo.</p><label class="field top-gap"><span>Sua aplicação em um caso novo</span><textarea id="lesson-note" placeholder="Escreva um exemplo e justifique a conclusão...">${esc(latestNote(l.id))}</textarea></label><div class="row wrap top-gap">${btn(ic('save')+'Salvar anotação','note','',`data-topic="${l.id}"`)}${btn('Praticar com 2 questões '+ic('arrow'),'practice','primary',`data-topic="${l.id}"`)}</div></article>`:tab==='reason'?`<section class="panel"><h2>Construa o raciocínio</h2><p class="muted top-gap">Percorra as oito etapas, sem pular da leitura para a memorização.</p><div class="accordions top-gap">${steps.map((step,i)=>`<details ${i===0?'open':''}><summary>${i+1}. ${step}</summary><div class="details-body">${esc([l.core,l.rule,l.limit,l.contrast,l.example,'Reescreva a regra como um item C/E e mude um detalhe. Qual palavra altera a conclusão?','Explique a regra sem consultar o material. Depois confira o que esqueceu.','Resolva um caso novo, mude os sujeitos ou requisitos e justifique o resultado.'][i])}</div></details>`).join('')}</div>${btn('Praticar com 2 questões','practice','primary full top-gap',`data-topic="${l.id}"`)}</section>`:`<section class="panel"><h2>Suas anotações</h2><p class="muted top-gap">Registre dúvidas, fundamentos e exemplos. As notas anteriores permanecem no histórico.</p><label class="field top-gap"><span>Explique com suas palavras</span><textarea id="lesson-note" style="min-height:250px" placeholder="O que compreendi? Com o que posso confundir?">${esc(latestNote(l.id))}</textarea></label>${btn(ic('save')+'Salvar anotação','note','primary full top-gap',`data-topic="${l.id}"`)}</section>`;
return header(esc(l.title),'Teoria, exemplos e aplicação antes de avançar.',link(ic('back')+'Voltar à trilha','#courses/'+l.d,'small'))+`<div class="study-layout"><div><div class="tabs" role="tablist" aria-label="Etapas de estudo">${[['theory','Teoria'],['examples','Exemplos'],['reason','Raciocínio'],['notes','Anotações']].map(([k,v])=>`<button role="tab" aria-selected="${tab===k}" class="${tab===k?'active':''}" data-act="tab" data-value="${k}">${v}</button>`).join('')}</div>${body}</div><aside class="panel study-aside"><h3>Seu caminho nesta aula</h3><div class="steps top-gap">${['Entender a teoria','Aplicar em exemplos','Responder 2 itens juntos','Corrigir e diagnosticar'].map((x,i)=>`<div class="step"><span class="step-num">0${i+1}</span><span>${x}</span></div>`).join('')}</div><div class="top-gap">${btn(ic('play')+'Iniciar questões','practice','primary full',`data-topic="${l.id}"`)}</div><p class="muted" style="font-size:.78rem;margin-top:16px">Sem gabarito antecipado. Itens autorais no estilo CEBRASPE.</p><div class="top-gap">${btn('Ver evidências de domínio','evidence','full small',`data-topic="${l.id}"`)}</div>${S.session?btn('Encerrar sessão','finish','ghost full top-gap'):''}</aside></div>`;}
function questionsPage(){if(!S.quiz){const seen=C.lessons.filter(l=>st(l.id).seen);return header('Questões','Itens autorais no estilo CEBRASPE. Responda em duplas, corrija e entenda a regra.')+`<div class="grid2"><section class="panel"><h2>Treino por assunto</h2><label class="field top-gap"><span>Escolha o assunto</span><select id="practice-topic">${C.lessons.map(l=>`<option value="${l.id}">${esc(disc(l.d).short+' • '+l.title)}</option>`).join('')}</select></label>${btn('Começar rodada de 2 itens','practice-select','primary full top-gap')}</section><section class="panel"><h2>Treino cumulativo</h2><p class="top-gap">Misture conteúdos já vistos, sem perder os assuntos antigos.</p><p class="muted top-gap">${seen.length} módulo(s) disponível(is) a partir do seu estudo.</p>${btn('Treinar conteúdos vistos','mixed','full outline top-gap',seen.length?'':'disabled')}</section></div>`;}return S.quiz.submitted?correction():quizView();}
function questionCard(q,index){const value=S.quiz.answers[q.id]||{};return`<article class="panel question"><div class="row between"><span class="question-number">ITEM ${String(index+1).padStart(2,'0')}</span><small>Estilo CEBRASPE • autoral</small></div><p class="statement">${esc(q.text)}</p><div class="answers" role="group" aria-label="Resposta do item ${index+1}">${[true,false].map(a=>`<button class="answer ${value.answer===a?'selected':''}" data-act="answer" data-qid="${q.id}" data-value="${a}" aria-pressed="${value.answer===a}">${a?'Certo':'Errado'}</button>`).join('')}</div><div class="top-gap"><small>Minha confiança</small><div class="confidence" style="margin-top:7px">${[['seguro','Seguro'],['duvida','Dúvida'],['chute','Chute']].map(([k,t])=>`<button class="chip ${value.confidence===k?'active':''}" data-act="confidence" data-qid="${q.id}" data-value="${k}" aria-pressed="${value.confidence===k}">${t}</button>`).join('')}</div></div><label class="field" style="margin-top:13px"><span class="muted" style="font-size:.78rem">Justifique seu raciocínio</span><textarea data-reason="${q.id}" placeholder="Qual regra sustenta sua resposta?">${esc(value.reason||'')}</textarea></label></article>`;}
function quizView(){const qz=S.quiz,all=qz.ids.map(id=>({...J.question(id),topic:C.lessons.find(l=>l.questions.some(q=>q.id===id)).id})),start=(qz.page||0)*2,shown=all.slice(start,start+2),complete=qz.ids.every(id=>typeof qz.answers[id]?.answer==='boolean'),isSim=qz.mode==='sim';return header(isSim?'Simulado cumulativo':'Rodada de aprendizagem',isSim?'As correções serão exibidas somente ao finalizar o simulado.':'Leia os dois itens e responda antes de conferir a correção.',`<span class="pill cyan">${ic('clock')}<span id="timer">${elapsed(qz.started)}</span></span>`)+`<div class="row between wrap bottom-gap"><span class="muted">${isSim?`Itens ${start+1}–${Math.min(start+2,all.length)} de ${all.length}`:'2 itens por rodada'}</span>${badge('Questões autorais','cyan')}</div><div class="grid2">${shown.map((q,i)=>questionCard(q,start+i)).join('')}</div><div class="quiz-actions">${btn('Salvar e sair','pause','ghost')}${isSim&&start?btn(ic('back')+'Anteriores','quiz-prev'):''}${isSim&&start+2<all.length?btn('Próximos '+ic('arrow'),'quiz-next','primary'):btn(isSim?'Finalizar simulado':`Corrigir as ${all.length} respostas`,'submit','primary',!isSim&&!complete?'disabled':'')}</div>${!isSim?notice('Uma resposta por item. Dúvida e chute também ajudam a orientar a revisão. Sua justificativa é registrada, mas não é avaliada automaticamente por IA.'):notice('Itens sem resposta serão registrados como em branco. A pontuação depende da configuração escolhida no início.')}`;}
function elapsed(start){const sec=Math.max(0,Math.floor((Date.now()-Date.parse(start))/1000));return String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0');}
function feedback(attempt){const q=J.question(attempt.qid),correct=attempt.answer===q.answer,l=lesson(attempt.topic);return`<article class="panel ${correct?'result-right':'result-wrong'}"><div class="row between wrap"><div class="row"><span class="result-icon">${ic(correct?'check':'close')}</span><h3>Item ${esc(q.id.split('-q')[1])} • ${correct?'Resposta correta':attempt.answer===null?'Em branco':'Rever o raciocínio'}</h3></div>${badge(disc(l.d).short)}</div><p class="statement">${esc(q.text)}</p><div class="row wrap gap-sm">${badge('Sua resposta: '+(attempt.answer===null?'Em branco':attempt.answer?'Certo':'Errado'),correct?'green':'red')}${badge('Gabarito: '+(q.answer?'Certo':'Errado'),'cyan')}</div><p class="top-gap">${esc(q.explanation)}</p><div class="top-gap">${source(l)}</div>${!correct?`<label class="field top-gap"><span>Qual foi a causa principal?</span><select data-cause="${attempt.id}"><option value="">Selecione para registrar</option>${causes.map(c=>`<option ${causeFor(attempt)===c?'selected':''}>${c}</option>`).join('')}</select></label>`:''}</article>`;}
const causes=['Conhecimento','Atenção','Interpretação','Confusão conceitual','Exceção','Aplicação','Pegadinha','Tempo'];
function quizAttempts(){return ae().filter(e=>e.type==='attempt'&&e.round===S.quiz?.id);}
function correction(){const ats=quizAttempts(),correct=ats.filter(e=>e.answer===J.question(e.qid).answer).length,pct=ats.length?Math.round(correct/ats.length*100):0;return header('Correção da rodada','A regra e o detalhe decisivo vêm antes da próxima rodada.')+`<div class="panel result-summary bottom-gap"><div class="ring" style="--value:${pct}"><div>${correct}/${ats.length}</div></div><div><h2>${correct} de ${ats.length} acertos</h2><p class="top-gap">${correct===ats.length?'Bom resultado. Confirme se consegue explicar e aplicar em outro contexto.':'Revise a regra e classifique os erros antes de continuar.'}</p><small>Um acerto por chute ou sem justificativa não comprova domínio.</small></div></div><div class="stack">${ats.map(feedback).join('')}</div><div class="quiz-actions">${btn('Voltar à teoria','back-theory')}${btn('Nova rodada','next-round','primary')}${btn('Encerrar sessão','finish','outline')}</div>`;}
function causeFor(a){return ae().filter(e=>e.type==='diagnosis'&&e.attempt===a.id).at(-1)?.cause||a.cause||'A classificar';}
function errorsPage(){let es=J.errors(db());if(S.errorFilter==='pending')es=es.filter(e=>!e.resolved);if(S.errorFilter==='resolved')es=es.filter(e=>e.resolved);if(S.discipline!=='all')es=es.filter(e=>lesson(e.topic).d===S.discipline);return header('Banco de erros','Transforme erros em revisão. O registro original permanece no histórico.')+`<div class="row between wrap bottom-gap"><div class="filters" style="margin:0">${[['pending','Pendentes'],['resolved','Revisados'],['all','Todos']].map(([k,v])=>`<button class="chip ${S.errorFilter===k?'active':''}" data-act="error-filter" data-value="${k}">${v}</button>`).join('')}</div><select id="error-discipline" style="width:auto;max-width:100%" aria-label="Filtrar disciplina"><option value="all">Todas as disciplinas</option>${C.disciplines.map(d=>`<option value="${d.id}" ${S.discipline===d.id?'selected':''}>${esc(d.short)}</option>`).join('')}</select></div>${es.length?`<div class="grid2">${es.map(e=>`<article class="panel"><div class="row between wrap bottom-gap">${badge(disc(lesson(e.topic).d).short,'cyan')}<small>${date(e.at)}</small></div><h3>${esc(lesson(e.topic).title)}</h3><p style="margin:12px 0;font-size:.9rem">${esc(J.question(e.qid).text)}</p><div class="row wrap gap-sm">${badge(causeFor(e),e.resolved?'green':'red')}${e.resolved?badge('Revisitado com acerto','green'):''}</div><div class="top-gap">${btn('Entender este erro '+ic('chevron'),'error-detail','full',`data-id="${e.id}"`)}</div></article>`).join('')}</div>`:empty('Nenhum erro nesta seleção','As questões erradas ou em branco entram aqui automaticamente, com sua resposta e a explicação.',link('Ir para questões','#questions','primary'),'shield')}`;}
function reviews(){const seen=C.lessons.filter(l=>st(l.id).seen||st(l.id).total),now=new Date();const list=seen.filter(l=>{const d=J.dueDate(db(),l.id);return S.reviewTab==='all'||S.reviewTab==='pending'&&(!d||d<=now)||S.reviewTab==='future'&&d&&d>now;}).sort((a,b)=>(J.dueDate(db(),a.id)||0)-(J.dueDate(db(),b.id)||0));return header('Revisões','Recupere a regra, aplique em outro caso e ajuste o intervalo pelo desempenho.')+`<div class="filters">${[['pending','Pendentes'],['future','Próximas'],['all','Todos os vistos']].map(([k,t])=>`<button class="chip ${S.reviewTab===k?'active':''}" data-act="review-tab" data-value="${k}">${t}</button>`).join('')}</div>${list.length?`<div class="grid2">${list.map(l=>{const due=J.dueDate(db(),l.id);return`<article class="panel"><div class="row bottom-gap"><div class="review-date">${ic('refresh')}</div><div class="grow"><h3>${esc(l.title)}</h3><small>${esc(disc(l.d).short)} · ${due?date(due):'Primeira aplicação pendente'}</small></div></div><p style="font-size:.88rem">Explique a regra sem consultar e pratique com 2 itens.</p>${btn('Revisar agora','review','primary full top-gap',`data-topic="${l.id}"`)}</article>`;}).join('')}</div>`:empty('Nenhuma revisão nesta seleção','As revisões são criadas a partir das suas respostas. Você também pode revisar qualquer conteúdo visto.',link('Ver conteúdos','#courses','primary'),'refresh')}<div class="top-gap">${notice('Intervalos de referência: 1, 3, 7 e 14 dias. Dificuldade registrada antecipa a recuperação. Domingo pode ser usado para revisão cumulativa; não há bloqueio por dia da semana.')}</div>`;}
function sim(){const studied=C.lessons.filter(l=>st(l.id).seen).length;return header('Simulado cumulativo','Misture disciplinas, registre tempo e analise erros antes de aumentar a carga.')+`<div class="grid2"><section class="panel"><h2>Monte seu treino</h2><label class="field top-gap"><span>Conteúdos incluídos</span><select id="sim-scope"><option value="studied">Somente módulos já vistos (${studied})</option><option value="all">Todo o banco introdutório</option></select></label><fieldset style="border:0;padding:0;margin:22px 0"><legend class="muted" style="font-size:.85rem">Disciplinas</legend>${C.disciplines.map(d=>`<label class="check-row"><input type="checkbox" name="sim-discipline" value="${d.id}" checked><span>${esc(d.name)}</span></label>`).join('')}</fieldset><div class="grid2"><label class="field"><span>Quantidade desejada</span><select id="sim-count">${[10,20,40,50,60,70,80,90,100,110,120].map(n=>`<option ${n===40?'selected':''}>${n}</option>`).join('')}</select></label><label class="field"><span>Regra de pontuação</span><select id="sim-scoring"><option value="simple">Acertos e erros</option><option value="net">Líquida: +1 / −1</option></select></label></div>${btn(ic('play')+'Começar simulado','sim-start','primary full top-gap')}</section><aside class="stack" style="align-self:start"><section class="panel"><h2>Resistência com progressão</h2><p class="top-gap">A referência do método vai de 40 até 120 itens, condicionada ao desempenho, concentração e fadiga.</p><div class="top-gap">${notice('Se o banco selecionado for menor, o simulado terá apenas os itens disponíveis. Não repetimos questões para completar a quantidade.')}</div><p class="top-gap" style="font-size:.85rem">O cronômetro começa com o simulado. É possível navegar em duplas e deixar itens em branco. O gabarito aparece ao finalizar.</p></section>${link('Ver histórico de sessões','#history','full')}</aside></div>`;}
function result(id){const ats=ae().filter(e=>e.type==='attempt'&&e.round===id),session=ae().find(e=>e.type==='session'&&e.round===id);if(!ats.length)return empty('Resultado não encontrado','Selecione uma sessão do seu histórico.',link('Abrir histórico','#history','primary'));const right=ats.filter(e=>e.answer===J.question(e.qid).answer).length,blank=ats.filter(e=>e.answer===null).length,wrong=ats.length-right-blank,pct=Math.round(right/ats.length*100);return header('Resultado do simulado','Use o diagnóstico para escolher a próxima etapa.',link('Novo simulado','#sim','small'))+`<div class="grid3 stats-grid bottom-gap"><div class="panel stat"><small>Acertos</small><strong class="green">${right}</strong></div><div class="panel stat"><small>Erros</small><strong class="red">${wrong}</strong></div><div class="panel stat"><small>Em branco</small><strong class="amber">${blank}</strong></div></div><section class="panel result-summary bottom-gap"><div class="ring" style="--value:${pct}"><div>${pct}%</div></div><div><h2>${right} acertos em ${ats.length} itens</h2><p>${session?.scoring==='net'?`Pontuação líquida: ${right-wrong} (+1 / −1).`:'Pontuação simples: '+right+' acertos.'}</p><small>Tempo: ${session?Math.ceil(session.seconds/60)+' min':'não registrado'} · Treino autoral, não prova oficial.</small></div></section><section class="panel bottom-gap"><h2>Por disciplina</h2><div class="metric-bars top-gap">${C.disciplines.map(d=>{const a=ats.filter(e=>lesson(e.topic).d===d.id),r=a.filter(e=>e.answer===J.question(e.qid).answer).length;return a.length?`<div class="bar-row"><div class="row between"><span>${esc(d.short)}</span><span>${r}/${a.length}</span></div>${bar(r/a.length*100,d.color)}</div>`:'';}).join('')}</div></section><div class="row wrap bottom-gap">${link('Analisar banco de erros','#errors','primary')}${btn('Exportar continuidade','continuity')}</div><div class="accordions"><details><summary>Ver gabarito e explicações (${ats.length} itens)</summary><div class="details-body stack">${ats.map(feedback).join('')}</div></details></div>`;}
function chart(){const sessions=ae().filter(e=>e.type==='session').slice(-10);const vals=sessions.map(se=>{const a=ae().filter(e=>e.type==='attempt'&&se.attemptIds?.includes(e.id));return a.length?a.filter(e=>e.answer===J.question(e.qid).answer).length/a.length*100:0;});if(!vals.length)return`<p class="muted top-gap">O gráfico aparecerá após a primeira sessão concluída.</p>`;const points=vals.map((v,i)=>`${45+i*(500/Math.max(1,vals.length-1))},${145-v*1.2}`).join(' ');return`<svg class="chart" viewBox="0 0 580 180" role="img" aria-label="Aproveitamento nas últimas ${vals.length} sessões: ${vals.map(v=>Math.round(v)+'%').join(', ')}">${[0,50,100].map(v=>`<path d="M40 ${145-v*1.2}H555" stroke="var(--line)"/><text x="0" y="${150-v*1.2}">${v}%</text>`).join('')}<polyline points="${points}" fill="none" stroke="currentColor" stroke-width="3"/>${vals.map((v,i)=>`<circle cx="${45+i*(500/Math.max(1,vals.length-1))}" cy="${145-v*1.2}" r="4" fill="currentColor"/>`).join('')}<text x="40" y="175">Sessões concluídas →</text></svg>`;}
function mapPage(){const s=J.stats(db()),seen=C.lessons.filter(l=>st(l.id).seen).length,mastered=C.lessons.filter(l=>st(l.id).mastered).length;return header('Mapa cumulativo','Visto, em consolidação e dominado: estados diferentes, com evidências.',link('Histórico','#history','small'))+`<div class="grid3 stats-grid bottom-gap"><div class="panel stat">${ic('book')}<strong>${seen}/${C.lessons.length}</strong><small>Módulos vistos</small></div><div class="panel stat">${ic('file')}<strong>${s.total?s.accuracy+'%':'—'}</strong><small>Acertos nos itens</small></div><div class="panel stat">${ic('shield')}<strong>${mastered}</strong><small>Tópicos dominados</small></div></div><div class="grid2 bottom-gap"><section class="panel"><h2>Sua evolução real</h2><small>Últimas 10 sessões do ciclo atual</small>${chart()}</section><section class="panel"><h2>Progresso por disciplina</h2><div class="metric-bars top-gap">${C.disciplines.map(d=>{const ls=C.lessons.filter(l=>l.d===d.id),n=ls.filter(l=>st(l.id).seen).length;return`<div class="bar-row"><div class="row between"><span>${esc(d.short)}</span><span>${n}/${ls.length} vistos</span></div>${bar(n/ls.length*100,d.color)}</div>`;}).join('')}</div></section></div>${C.disciplines.map(d=>`<section class="accordions bottom-gap"><details><summary>${esc(d.name)} • ${C.lessons.filter(l=>l.d===d.id&&st(l.id).mastered).length} dominados</summary><div class="details-body"><div class="lesson-list">${C.lessons.filter(l=>l.d===d.id).map((l,i)=>{const state=st(l.id);return`<div class="panel topic-row"><span class="status-circle ${state.status}">${i+1}</span><div class="grow"><strong>${esc(l.title)}</strong><div style="margin-top:6px">${badge(statuses[state.status],colorStatus(state.status))}</div></div>${btn(ic('list'),'evidence','small',`data-topic="${l.id}" aria-label="Evidências de ${esc(l.title)}"`)}</div>`;}).join('')}</div><h3 class="top-gap">Aprofundamentos do edital-base</h3><p class="muted" style="margin:10px 0;font-size:.8rem">Checklist de estudo adicional. Marcar não declara domínio nem altera o desempenho.</p>${C.coverage[d.id].map((item,i)=>{const key=d.id+'-'+i,v=ae().filter(e=>e.type==='coverage'&&e.item===key).at(-1)?.done;return`<label class="check-row"><input type="checkbox" data-coverage="${key}" ${v?'checked':''}><span>${esc(item)}</span></label>`;}).join('')}</div></details></section>`).join('')}`;}
function history(){const all=db().events.filter(e=>e.type==='session').reverse(),cycles=new Set(db().events.filter(e=>e.type==='cycle').map(e=>e.next));return header('Histórico de sessões','Registros cumulativos. Novos ciclos preservam as sessões anteriores.',btn(ic('download')+'Exportar continuidade','continuity','small'))+notice(`Ciclo atual: ${ae().filter(e=>e.type==='session').length} sessão(ões). Arquivo completo: ${all.length} sessão(ões), ${cycles.size+1} ciclo(s).`)+`<div class="top-gap">${all.length?`<div class="timeline">${all.map((s,i)=>{const ats=db().events.filter(e=>s.attemptIds?.includes(e.id)),right=ats.filter(e=>e.answer===J.question(e.qid)?.answer).length;return`<article class="panel"><div class="row between wrap bottom-gap"><h3>${esc(s.title)}</h3>${badge(s.cycle===J.cycle(db())?'Ciclo atual':'Ciclo arquivado',s.cycle===J.cycle(db())?'cyan':'')}</div><p>${date(s.at)} · ${Math.ceil(s.seconds/60)} min · ${ats.length} itens · ${right} acertos</p><p class="top-gap">${esc(s.decision||'Revisar conforme diagnóstico.')}</p><div class="row wrap top-gap">${btn('Abrir resumo','session-detail','small',`data-id="${s.id}"`)}${s.mode==='sim'&&s.cycle===J.cycle(db())?link('Ver resultado','#result/'+s.round,'small outline'):''}</div></article>`;}).join('')}</div>`:empty('Seu histórico começa com a primeira sessão','Inicie um estudo e use “Encerrar sessão” após a correção para registrar o fechamento.',link('Começar estudo','#lesson/'+J.recommend(db()).lesson.id,'primary'),'clock')}</div>`;}
function sources(){return header('Fontes e atualização','Consulte textos oficiais e confirme alterações antes de aplicar uma regra.')+notice('Este aplicativo não pesquisa notícias nem atualiza leis automaticamente. Os links externos exigem internet. O edital de 2022 é apenas a base histórica do mapa.')+`<div class="grid2 top-gap source-list">${Object.entries(C.sources).filter(([,s])=>s[1]).map(([k,s])=>`<a class="panel menu-card" href="${s[1]}" target="_blank" rel="noopener noreferrer">${ic('external')}<div class="grow"><h3>${esc(s[0])}</h3><small>Consultar fonte de referência</small></div>${ic('chevron')}</a>`).join('')}</div><div class="panel top-gap"><h2>Como registrar uma atualização</h2><p class="top-gap">Confira fonte, data, vigência e eventual transição. Nas anotações, registre o dispositivo e o que mudou. Novas edições do conteúdo devem preservar as respostas já dadas e sua versão.</p><div class="row wrap top-gap"><a class="btn" href="https://www.gov.br/inss/pt-br" target="_blank" rel="noopener">INSS oficial ${ic('external')}</a><a class="btn" href="https://www.cebraspe.org.br/concursos/" target="_blank" rel="noopener">Concursos CEBRASPE ${ic('external')}</a></div></div>`;}
function settings(){const p=db().prefs;return header('Configurações e backup','Seu progresso individual fica neste navegador. Não há conta nem sincronização na nuvem.')+`<div class="grid2"><section class="panel"><h2>Preferências de estudo</h2><label class="field top-gap"><span>Como quer ser chamado(a)?</span><input id="profile-name" maxlength="80" value="${esc(p.name)}" placeholder="Seu nome (opcional)"></label><div class="settings-row"><div><strong>Tema do aplicativo</strong><p>Escolha a aparência.</p></div>${btn(ic(p.theme==='dark'?'sun':'moon')+(p.theme==='dark'?'Claro':'Escuro'),'theme','small')}</div><div class="settings-row"><div><strong>Tamanho do texto</strong><p>Leitura confortável.</p></div><div class="row gap-sm">${btn('A−','font-down','small','aria-label="Diminuir fonte"')}<span>${p.font}</span>${btn('A+','font-up','small','aria-label="Aumentar fonte"')}</div></div><label class="settings-row"><strong>Meta de referência</strong><select id="goal" aria-label="Meta diária">${[15,30,45,60,90].map(n=>`<option value="${n}" ${p.goal===n?'selected':''}>${n} min</option>`).join('')}</select></label><p class="muted" style="font-size:.8rem;margin-top:16px">A meta orienta o estudo; não limita o tempo nem obriga a avançar.</p>${btn('Salvar preferências','prefs','primary full top-gap')}</section><section class="panel"><div class="row bottom-gap"><div class="course-icon">${ic('database')}</div><div><h2>Proteja seu progresso</h2><small class="green">Armazenamento local</small></div></div><p>Exporte respostas, erros, notas e histórico em JSON. Use a importação para mesclar o histórico em outro aparelho.</p><div class="stack top-gap">${btn(ic('download')+'Baixar backup completo','export','primary full')}<a class="btn full" href="jarvis-estudante.html" download>Baixar aplicativo HTML</a>${btn(ic('upload')+'Importar backup','import','full')}${btn(ic('file')+'Exportar resumo para o JARVIS','continuity','full')}${btn(ic('shield')+'Solicitar armazenamento persistente','persistent','full')}</div><div class="top-gap">${notice('Limpar os dados do navegador pode apagar o progresso. O arquivo HTML, sozinho, não contém seu histórico. Guarde uma cópia de backup. O navegador decide se pode manter armazenamento persistente.',true)}</div></section><section class="panel fullrow"><h2>Novo ciclo, histórico preservado</h2><p class="top-gap">Recomece a trilha com contadores zerados. As sessões e respostas do ciclo anterior continuam no histórico e no backup.</p><div class="top-gap">${btn('Iniciar novo ciclo','new-cycle','danger')}</div></section></div>`;}
function more(){return header('Seu espaço de estudos','Tudo o que você precisa para aprender, revisar e acompanhar sua evolução.')+`<div class="menu-grid">${navs.map(([p,i])=>`<a class="panel menu-card" href="#${p}"><div class="course-icon">${ic(i)}</div><div class="grow"><h3>${names[p]}</h3><small>${p==='settings'?'Preferências, importação e exportação':'Abrir '+names[p].toLocaleLowerCase('pt-BR')}</small></div>${ic('chevron')}</a>`).join('')}</div>`;}
function render(){applyPrefs();const r=route();let html='';try{html=({home,more,questions:questionsPage,reviews,sim,map:mapPage,history,sources,settings,courses:()=>courses(r.id),lesson:()=>study(r.id),errors:errorsPage,result:()=>result(r.id)})[r.page]();}catch(e){console.error(e);html=empty('Não foi possível abrir esta tela','O histórico está preservado. Exporte um backup e volte ao início.',btn('Exportar backup','export','primary'));}app.innerHTML=shell(html);clearInterval(timer);if(S.quiz&&!S.quiz.submitted)timer=setInterval(()=>{const e=document.getElementById('timer');if(e)e.textContent=elapsed(S.quiz.started);},1000);}
function openModal(title,body,actions=''){lastFocus=document.activeElement;document.getElementById('modal-root').innerHTML=`<div class="overlay" data-act="overlay-close"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="row between bottom-gap"><h2 id="dialog-title">${title}</h2><button class="icon-btn" data-act="modal-close" aria-label="Fechar janela">${ic('close')}</button></div>${body}<div class="actions">${actions||btn('Fechar','modal-close')}</div></section></div>`;document.body.style.overflow='hidden';document.querySelector('.dialog button, .dialog input, .dialog select')?.focus();}
function closeModal(){document.getElementById('modal-root').innerHTML='';document.body.style.overflow='';lastFocus?.isConnected&&lastFocus.focus();}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function exportBackup(){download('jarvis-backup-'+new Date().toISOString().slice(0,10)+'.json',store.export());notify('Backup preparado para download. Guarde o arquivo em uma pasta segura.');}
function continuity(){const es=ae(),s=J.stats(db()),rec=J.recommend(db()),lines=['# JARVIS Estudante — resumo de continuidade','Gerado em: '+new Date().toLocaleString('pt-BR'),'Ciclo: '+J.cycle(db()),'Base: módulos autorais introdutórios; edital histórico 2022.','',`Sessões: ${es.filter(e=>e.type==='session').length}; itens: ${s.total}; acertos: ${s.right}; erros: ${s.wrong}; em branco: ${s.blank}.`,'','## Mapa atual',...C.lessons.map(l=>`- ${disc(l.d).short} / ${l.title}: ${statuses[st(l.id).status]}`),'','## Erros para recuperar',...J.errors(db()).filter(e=>!e.resolved).map(e=>`- ${lesson(e.topic).title}: ${J.question(e.qid).text} | causa: ${causeFor(e)} | ${J.question(e.qid).explanation}`),'','## Próximo passo sugerido',rec.lesson.title+' — '+rec.reason,'','## Método','Teoria → exemplos → 2 itens juntos → correção → diagnóstico → recuperação ou avanço.','Não confundir visto com dominado. Não inventar percentual de edital.','Prioridade máxima: Previdenciário. Reforço: Constitucional. Manter as sete disciplinas.','','## Sessões do ciclo',...es.filter(e=>e.type==='session').map(e=>`- ${e.at}: ${e.title}. ${e.decision||''}`),'','## Notas',...es.filter(e=>e.type==='note').map(e=>`- ${lesson(e.topic)?.title}: ${e.text}`)];download('JARVIS-continuidade.md',lines.join('\n'),'text/markdown;charset=utf-8');notify('Resumo de continuidade preparado.');}
function evidence(id){const l=lesson(id),s=st(id);openModal('Evidências de domínio',`<h3>${esc(l.title)}</h3><p class="muted top-gap">O domínio exige compreensão e aplicação, não apenas marcar uma lista.</p><div class="top-gap">${notice(`Evidências registradas: ${s.unique}/4 itens distintos corretos com confiança e justificativa de pelo menos 20 caracteres; ${s.rounds}/2 rodadas; ${s.accuracy}% de acertos. A justificativa é uma autoavaliação, sem correção semântica automática.`)}</div>${['Compreendi a teoria e consigo explicar.','Justifiquei a regra sem consultar.','Apliquei em um caso novo.','Cobri os subtemas relevantes do módulo.'].map((t,i)=>`<label class="check-row"><input type="checkbox" name="evidence" ${s.evidence[i]?'checked':''}><span>${t}</span></label>`).join('')}<p class="muted" style="font-size:.8rem">${s.eligible?'Você reúne os critérios quantitativos; confirme somente as evidências reais.':'Continue estudando: os critérios quantitativos ainda não foram atingidos. As marcações podem ser salvas para acompanhar sua autoavaliação.'}</p>`,btn('Cancelar','modal-close')+btn('Salvar evidências','save-evidence','primary',`data-topic="${id}"`));}
function beginQuiz(topics,mode='learn',ids=null,count=2,scoring='simple'){if(S.quiz&&!S.quiz.submitted){openModal('Há uma atividade em andamento','<p class="muted">Continue a rodada já salva antes de iniciar outra. Suas respostas em andamento estão preservadas.</p>',btn('Fechar','modal-close')+btn('Continuar atividade','resume','primary'));return;}const qs=ids?ids.map(id=>({id})):J.pick(db(),topics,count);if(!qs.length){notify('Não há itens disponíveis nesta seleção.',true);return;}const l=lesson(topics[0]);startSession(l,mode);S.quiz={id:J.uid(),ids:qs.map(q=>q.id),answers:{},mode,scoring,started:new Date().toISOString(),page:0,submitted:false};persistDraft();go('questions');}
async function finishSession(afterSim=false){if(!S.session){notify('Nenhuma sessão aberta.');return;}if(S.quiz&&!S.quiz.submitted&&!afterSim){openModal('Atividade ainda em andamento','<p class="muted">Finalize a correção ou o simulado antes de encerrar. Para parar agora, use “Salvar e sair”; a atividade será retomada depois.</p>',btn('Voltar','modal-close')+btn('Continuar atividade','resume','primary'));return;}const session=S.session,ats=ae().filter(e=>e.type==='attempt'&&e.session===session.id);const right=ats.filter(e=>e.answer===J.question(e.qid).answer).length;const decision=ats.length&&right/ats.length<.7?'Recuperar: retomar a regra e praticar em um novo contexto.':'Revisar e confirmar a aplicação antes de avançar.';
 const payload={id:session.id,topic:session.topic,title:(session.mode==='sim'?'Simulado cumulativo':lesson(session.topic).title),seconds:Math.max(0,Math.round((Date.now()-Date.parse(session.started))/1000)),mode:session.mode,round:S.quiz?.id||'',attemptIds:ats.map(e=>e.id),decision,scoring:S.quiz?.scoring||'simple'};
 if(!(await save([event('session',payload)])))return;S.session=null;S.quiz=null;persistDraft();notify('Sessão concluída. Histórico e diagnóstico salvos no aparelho.');if(!afterSim)go('history');}
async function submitQuiz(){const qz=S.quiz;if(!qz||qz.submitted)return;if(qz.mode!=='sim'&&!qz.ids.every(id=>typeof qz.answers[id]?.answer==='boolean')){notify('Responda aos dois itens antes de corrigir.',true);return;}
 if(qz.mode==='sim'&&!qz.confirmed){const blank=qz.ids.filter(id=>typeof qz.answers[id]?.answer!=='boolean').length;openModal('Finalizar simulado?',`<p class="muted">${blank?`${blank} item(ns) será(ão) registrado(s) em branco. `:''}O gabarito será exibido e as respostas serão preservadas no histórico.</p>`,btn('Continuar respondendo','modal-close')+btn('Finalizar e corrigir','confirm-sim','primary'));return;}
 const events=qz.ids.map(id=>{const value=qz.answers[id]||{},l=C.lessons.find(l=>l.questions.some(q=>q.id===id));return event('attempt',{topic:l.id,qid:id,answer:typeof value.answer==='boolean'?value.answer:null,confidence:value.confidence||'duvida',reason:String(value.reason||'').slice(0,4000),cause:'',round:qz.id,session:S.session.id,contentVersion:C.version});});
 if(!(await save(events)))return;qz.submitted=true;persistDraft();if(qz.mode==='sim'){const id=qz.id;await finishSession(true);if(!S.session)go('result/'+id);else render();}else{render();window.scrollTo(0,0);}}
const actions={
 drawer:()=>{S.drawer=true;render();document.querySelector('.drawer-close')?.focus();},'drawer-close':()=>{S.drawer=false;render();},'overlay-close':el=>{if(el===document.querySelector('.overlay'))closeModal();},'modal-close':closeModal,
 theme:async()=>{await save([],{theme:db().prefs.theme==='dark'?'light':'dark'});render();},'font-up':async()=>{await save([],{font:Math.min(20,db().prefs.font+2)});render();},'font-down':async()=>{await save([],{font:Math.max(16,db().prefs.font-2)});render();},
 filter:el=>{S.filter=el.dataset.value;render();},tab:el=>{S.tab=el.dataset.value;render();},
 read:async el=>{const l=lesson(el.dataset.topic);startSession(l);if(!st(l.id).seen&&!(await save([event('read',{topic:l.id})])))return;S.tab='examples';notify('Introdução registrada como vista. Agora aplique a regra.');render();},
 note:async el=>{const l=lesson(el.dataset.topic),text=document.getElementById('lesson-note').value.trim();if(!text){notify('Escreva uma anotação antes de salvar.');return;}startSession(l);if(await save([event('note',{topic:l.id,text:text.slice(0,10000)})]))notify('Anotação salva. Versões anteriores preservadas.');},
 practice:el=>beginQuiz([el.dataset.topic]),'practice-select':()=>beginQuiz([document.getElementById('practice-topic').value]),mixed:()=>beginQuiz(C.lessons.filter(l=>st(l.id).seen).map(l=>l.id),'mixed'),review:el=>beginQuiz([el.dataset.topic],'review'),
 answer:el=>{const q=S.quiz;if(!q||q.submitted)return;const v=q.answers[el.dataset.qid]||(q.answers[el.dataset.qid]={});v.answer=el.dataset.value==='true';persistDraft();const pos=window.scrollY;render();window.scrollTo(0,pos);},
 confidence:el=>{const q=S.quiz;if(!q||q.submitted)return;const v=q.answers[el.dataset.qid]||(q.answers[el.dataset.qid]={});v.confidence=el.dataset.value;persistDraft();const pos=window.scrollY;render();window.scrollTo(0,pos);},
 'quiz-next':()=>{S.quiz.page++;persistDraft();render();window.scrollTo(0,0);},'quiz-prev':()=>{S.quiz.page=Math.max(0,S.quiz.page-1);persistDraft();render();window.scrollTo(0,0);},submit:submitQuiz,'confirm-sim':async()=>{S.quiz.confirmed=true;closeModal();await submitQuiz();},
 pause:()=>{persistDraft();notify('Atividade salva para continuar neste navegador.');go('home');},resume:()=>{closeModal();go('questions');},
 'next-round':()=>{const topics=[...new Set(quizAttempts().map(e=>e.topic))];beginQuiz(topics,S.quiz.mode);},'back-theory':()=>{const topic=quizAttempts()[0]?.topic||S.session?.topic;S.tab='theory';go('lesson/'+topic);},finish:async()=>{await finishSession();},
 'error-filter':el=>{S.errorFilter=el.dataset.value;render();},'review-tab':el=>{S.reviewTab=el.dataset.value;render();},
 'error-detail':el=>{const a=ae().find(e=>e.id===el.dataset.id);if(!a)return;openModal('Entenda este erro',feedback(a)+`<label class="field top-gap"><span>O que observar na próxima tentativa?</span><textarea id="error-note" placeholder="Registre a regra e o detalhe decisivo...">${esc(latestNote(a.topic))}</textarea></label>`,btn('Salvar nota','error-note','',`data-topic="${a.topic}"`)+btn('Treinar novamente','retry-error','primary',`data-topic="${a.topic}"`));},
 'error-note':async el=>{const text=document.getElementById('error-note').value.trim();if(text&&await save([event('note',{topic:el.dataset.topic,text:text.slice(0,10000)})]))notify('Nota de recuperação salva.');},'retry-error':el=>{closeModal();beginQuiz([el.dataset.topic],'review');},
 evidence:el=>evidence(el.dataset.topic),'save-evidence':async el=>{const checks=[...document.querySelectorAll('input[name=evidence]')].map(e=>e.checked);if(await save([event('evidence',{topic:el.dataset.topic,checks})])){closeModal();render();notify('Autoavaliação salva. Status calculado pelas evidências registradas.');}},
 'sim-start':()=>{if(S.session){openModal('Encerre a sessão atual','<p class="muted">Conclua a atividade em andamento para registrar seu tempo e diagnóstico antes de iniciar o simulado.</p>',btn('Cancelar','modal-close')+btn('Ir à sessão','resume','primary'));return;}const selected=[...document.querySelectorAll('input[name=sim-discipline]:checked')].map(e=>e.value),scope=document.getElementById('sim-scope').value,ls=C.lessons.filter(l=>selected.includes(l.d)&&(scope==='all'||st(l.id).seen));if(!ls.length){notify('Selecione disciplinas com módulos já vistos ou use todo o banco.',true);return;}const requested=Number(document.getElementById('sim-count').value),available=ls.reduce((n,l)=>n+l.questions.length,0);if(available<requested)notify(`Serão usados ${available} itens disponíveis, sem repetição.`);beginQuiz(ls.map(l=>l.id),'sim',null,Math.min(requested,available),document.getElementById('sim-scoring').value);},
 'session-detail':el=>{const s=db().events.find(e=>e.type==='session'&&e.id===el.dataset.id),ats=db().events.filter(e=>s.attemptIds?.includes(e.id));openModal(esc(s.title),`<p class="muted">${date(s.at)} · ${Math.ceil(s.seconds/60)} min</p><p class="top-gap">${esc(s.decision)}</p><div class="accordions top-gap">${ats.map(a=>`<details><summary>${esc(J.question(a.qid).text)}</summary><div class="details-body">Sua resposta: ${a.answer===null?'Em branco':a.answer?'Certo':'Errado'}. Gabarito: ${J.question(a.qid).answer?'Certo':'Errado'}.<br>${esc(J.question(a.qid).explanation)}${a.reason?'<p>Justificativa: '+esc(a.reason)+'</p>':''}</div></details>`).join('')||'<p class="muted">Sessão de leitura, sem itens respondidos.</p>'}</div>`,btn('Fechar','modal-close')+btn('Exportar continuidade','continuity'));},
 prefs:async()=>{if(await save([],{name:document.getElementById('profile-name').value.trim(),goal:Number(document.getElementById('goal').value)})){notify('Preferências salvas.');render();}},export:exportBackup,continuity,
 import:()=>document.getElementById('backup-file').click(),
 'confirm-import':async()=>{if(!pendingImport)return;exportBackup();if(await store.restore(pendingImport).then(()=>true).catch(e=>{notify(e.message,true);return false;})){pendingImport=null;S.session=null;S.quiz=null;persistDraft();closeModal();render();notify('Histórico importado e mesclado, sem excluir registros existentes.');}},
 'new-cycle':()=>openModal('Iniciar novo ciclo?',`<p class="muted">Os contadores da trilha começarão do zero. Todo o histórico anterior será arquivado e continuará no backup. ${S.quiz&&!S.quiz.submitted?'Há uma atividade em andamento: finalize-a primeiro.':''}</p><label class="field top-gap"><span>Digite NOVO para confirmar</span><input id="cycle-confirm" autocomplete="off" placeholder="NOVO"></label>`,btn('Cancelar','modal-close')+btn('Arquivar ciclo e começar','confirm-cycle','danger',S.quiz&&!S.quiz.submitted?'disabled':'')),
 'confirm-cycle':async()=>{if(document.getElementById('cycle-confirm').value!=='NOVO'){notify('Digite NOVO para confirmar.');return;}exportBackup();if(S.session){await finishSession();if(S.session)return;}if(await save([event('cycle',{next:J.uid()})])){S.quiz=null;S.session=null;persistDraft();closeModal();go('home');notify('Novo ciclo iniciado. O histórico anterior foi preservado.');}},
 persistent:async()=>{if(!navigator.storage?.persist){notify('Este navegador não oferece essa opção. Use backups.');return;}try{const ok=await navigator.storage.persist();notify(ok?'Armazenamento persistente autorizado pelo navegador.':'O navegador não autorizou persistência. Continue exportando backups.');}catch{notify('Não foi possível solicitar persistência. Use backups.',true);}},
 speak:el=>{if(!('speechSynthesis'in window)){notify('Leitura em voz alta indisponível neste navegador.');return;}speechSynthesis.cancel();const l=lesson(el.dataset.topic),u=new SpeechSynthesisUtterance(l.title+'. '+l.core+'. '+l.rule);u.lang='pt-BR';u.onerror=()=>notify('A voz não está disponível. O texto continua acessível.');speechSynthesis.speak(u);}
};
document.addEventListener('click',async e=>{const el=e.target.closest('[data-act]');if(!el||el.disabled)return;if(el.dataset.act==='overlay-close'&&e.target!==el)return;const action=actions[el.dataset.act];if(!action)return;e.preventDefault();if(S.busy)return;S.busy=true;try{await action(el);}catch(error){console.error(error);notify('A ação não pôde ser concluída: '+error.message,true);}finally{S.busy=false;}});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.reason&&S.quiz&&!S.quiz.submitted){const a=S.quiz.answers[t.dataset.reason]||(S.quiz.answers[t.dataset.reason]={});a.reason=t.value;persistDraft();}if(t.id==='topic-search'){S.search=t.value;const pos=t.selectionStart;render();const field=document.getElementById('topic-search');field?.focus();field?.setSelectionRange(pos,pos);}});
document.addEventListener('change',async e=>{const t=e.target;if(t.id==='error-discipline'){S.discipline=t.value;render();}if(t.dataset.cause){const a=ae().find(e=>e.id===t.dataset.cause);if(a&&t.value&&await save([event('diagnosis',{attempt:a.id,cause:t.value})]))notify('Causa registrada sem alterar a resposta original.');}if(t.dataset.coverage)await save([event('coverage',{item:t.dataset.coverage,done:t.checked})]);});
document.getElementById('backup-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>8*1024*1024)throw Error('O arquivo excede o limite de 8 MB.');pendingImport=J.validate(JSON.parse(await file.text()));openModal('Mesclar backup?',`<p class="muted">O arquivo tem ${pendingImport.events.length} registros. Eles serão mesclados pelo identificador, sem duplicar ou excluir o histórico existente. Suas preferências atuais serão mantidas. Uma cópia do estado atual será baixada antes da importação.</p>`,btn('Cancelar','modal-close')+btn('Exportar atual e mesclar','confirm-import','primary'));}catch(error){notify('Backup recusado: '+error.message,true);}finally{e.target.value='';}});
document.addEventListener('keydown',e=>{const modal=document.querySelector('.dialog');if(e.key==='Escape'){if(modal)closeModal();else if(S.drawer){S.drawer=false;render();}}if(modal&&e.key==='Tab'){const list=[...modal.querySelectorAll('button:not(:disabled),a[href],input,select,textarea,[tabindex="0"]')];const first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',()=>{S.drawer=false;S.tab='theory';closeModal();render();window.scrollTo(0,0);document.getElementById('main')?.focus({preventScroll:true});});
window.addEventListener('storage',e=>{if(e.key===J.KEY){try{const v=J.validate(JSON.parse(e.newValue));store.db=J.merge(v,db());store.db.prefs=v.prefs;render();notify('Progresso atualizado por outra aba.');}catch{notify('Não foi possível ler uma atualização de outra aba. Exporte um backup.',true);}}});
window.addEventListener('pagehide',()=>{persistDraft();window.speechSynthesis?.cancel?.();});
if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{console.info('Cache offline não disponível nesta origem. O progresso local continua ativo.');});
matchMedia('(max-width:900px)').addEventListener('change',()=>render());
if(!location.hash)window.history.replaceState(null,'','#home');render();
})();
